//TMAXPROC PROC A=default,B=default
//PSTEP1
EXEC PGM=TMAXSOFT,PARM=&A
//PSTEP2
EXEC PGM=TMAXSOFT,PARM=&B
//PEND
//STEP1
EXEC TMAXPROC,A=,B=step1

